/**
 * Finish Guard — C1.5 Ghost Deliverable Enforcement (FM-3.1).
 *
 * Validates that every deliverable path in a finish() call exists on disk.
 * Throws a hard error if any are missing, forcing the agent to either
 * write the file or remove it from the deliverables list.
 *
 * Integration: Import `validateFinishDeliverables()` in the finish tool
 * handler (manager.ts) and call it before returning success.
 *
 * Uses only Node.js built-in modules — no external dependencies.
 */

import { existsSync } from "node:fs";
import { resolve, isAbsolute } from "node:path";

// ── Interfaces ────────────────────────────────────────────────────────

/** A deliverable declared in a finish() call. */
export interface FinishDeliverable {
  path: string;
  description?: string;
}

/** Result of the ghost-deliverable validation. */
export interface FinishValidationResult {
  /** `true` when all deliverables exist on disk. */
  valid: boolean;
  /** Paths that were validated and exist. */
  existingPaths: string[];
  /** Paths that were declared but don't exist on disk. */
  missingPaths: string[];
  /** Human-readable error message (present only when `valid === false`). */
  error?: string;
}

// ── Constants ─────────────────────────────────────────────────────────

/** Default project root used to resolve relative paths. */
const DEFAULT_PROJECT_ROOT = "/app";

/** Statuses that require deliverable validation. */
const STATUSES_REQUIRING_VALIDATION = new Set(["success", "partial"]);

// ── Public API ────────────────────────────────────────────────────────

/**
 * Validate that all declared deliverables exist on disk.
 *
 * @param deliverables  Array of deliverable objects from the finish() call.
 * @param status        The finish status (only "success" and "partial" are validated).
 * @param projectRoot   Root directory for resolving relative paths (default: `/app`).
 * @returns A {@link FinishValidationResult} describing which paths are valid/missing.
 *
 * @example
 * ```ts
 * const result = validateFinishDeliverables(
 *   [{ path: "src/foo.ts", description: "New module" }],
 *   "success"
 * );
 * if (!result.valid) throw new Error(result.error);
 * ```
 */
export function validateFinishDeliverables(
  deliverables: FinishDeliverable[] | undefined | null,
  status: string,
  projectRoot: string = DEFAULT_PROJECT_ROOT,
): FinishValidationResult {
  // Only validate for success/partial — failure/blocked may legitimately have no files
  if (!STATUSES_REQUIRING_VALIDATION.has(status)) {
    return { valid: true, existingPaths: [], missingPaths: [] };
  }

  // No deliverables declared — nothing to validate
  if (!deliverables || deliverables.length === 0) {
    return { valid: true, existingPaths: [], missingPaths: [] };
  }

  const existingPaths: string[] = [];
  const missingPaths: string[] = [];

  for (const deliverable of deliverables) {
    const rawPath = deliverable.path;

    if (!rawPath || typeof rawPath !== "string" || rawPath.trim() === "") {
      missingPaths.push(rawPath || "(empty path)");
      continue;
    }

    // Normalize: resolve relative paths against project root
    const resolvedPath = isAbsolute(rawPath)
      ? rawPath
      : resolve(projectRoot, rawPath);

    if (existsSync(resolvedPath)) {
      existingPaths.push(rawPath);
    } else {
      missingPaths.push(rawPath);
    }
  }

  if (missingPaths.length === 0) {
    return { valid: true, existingPaths, missingPaths: [] };
  }

  const missingList = missingPaths.map((p) => `'${p}'`).join(", ");
  const error =
    `FM-3.1 Ghost Deliverable: The following file(s) do not exist on disk: ${missingList}. ` +
    `You cannot claim them as deliverables. Write the file(s) or remove them from the deliverables list.`;

  return { valid: false, existingPaths, missingPaths, error };
}

/**
 * Convenience wrapper that throws on validation failure.
 * Designed to be called directly in the finish tool handler.
 *
 * @param deliverables  Array of deliverable objects from the finish() call.
 * @param status        The finish status.
 * @param projectRoot   Root directory for resolving relative paths.
 * @throws Error with FM-3.1 message if any deliverables are missing.
 */
export function enforceFinishDeliverables(
  deliverables: FinishDeliverable[] | undefined | null,
  status: string,
  projectRoot: string = DEFAULT_PROJECT_ROOT,
): void {
  const result = validateFinishDeliverables(deliverables, status, projectRoot);
  if (!result.valid) {
    throw new Error(result.error);
  }
}

/**
 * Ops Gate Logging (P61).
 *
 * Provides append-only JSONL-backed ops-receipt logging.
 * Receipts are stored in `.state/ops-receipts.jsonl` by default, but every
 * function accepts an optional `basePath` for testability.
 *
 * Uses only Node.js built-in modules — no external dependencies.
 */

import { readFileSync, appendFileSync, existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";

// ── Interfaces ────────────────────────────────────────────────────────

/** A single ops receipt entry. */
export interface OpsReceipt {
  id: string;
  action: string;
  result: string;
  context: Record<string, unknown>;
  timestamp: string;
  agent?: string;
}

// ── Helpers ───────────────────────────────────────────────────────────

/** Default base path for the JSONL file. */
const DEFAULT_BASE = join(process.cwd(), ".state");

/** Resolve the full path to the ops-receipts JSONL file. */
function filePath(basePath: string): string {
  return join(basePath, "ops-receipts.jsonl");
}

/**
 * Ensure the target directory exists (creates it recursively if needed).
 */
function ensureDir(basePath: string): void {
  if (!existsSync(basePath)) {
    mkdirSync(basePath, { recursive: true });
  }
}

/**
 * Read and parse every valid JSON line from the receipts file.
 * Silently skips empty or corrupt lines.
 */
function readAll(basePath: string): OpsReceipt[] {
  const fp = filePath(basePath);
  if (!existsSync(fp)) return [];

  const raw = readFileSync(fp, "utf-8");
  const receipts: OpsReceipt[] = [];

  for (const line of raw.split("\n")) {
    const trimmed = line.trim();
    if (trimmed.length === 0) continue;
    try {
      receipts.push(JSON.parse(trimmed) as OpsReceipt);
    } catch {
      // skip corrupt lines
    }
  }

  return receipts;
}

// ── Public API ────────────────────────────────────────────────────────

/**
 * Log an ops receipt and append it to the ledger.
 *
 * @param action   The action performed (e.g. "deploy", "rollback").
 * @param result   Outcome description (e.g. "success", "failed").
 * @param context  Arbitrary metadata object. If it contains an `agent`
 *                 property (string), that value is promoted to the
 *                 top-level `agent` field on the receipt.
 * @param basePath Directory containing `ops-receipts.jsonl` (default `.state/`).
 */
export function logOpsReceipt(
  action: string,
  result: string,
  context: Record<string, unknown>,
  basePath: string = DEFAULT_BASE,
): void {
  ensureDir(basePath);

  const receipt: OpsReceipt = {
    id: randomUUID(),
    action,
    result,
    context,
    timestamp: new Date().toISOString(),
  };

  // Promote agent from context if available
  if (typeof context.agent === "string") {
    receipt.agent = context.agent;
  }

  appendFileSync(filePath(basePath), JSON.stringify(receipt) + "\n", "utf-8");
}

/**
 * Retrieve receipts from the ledger, optionally filtering.
 *
 * @param filter    Optional filter: `action` matches exact action string,
 *                  `since` keeps only receipts whose timestamp >= the value.
 * @param basePath  Directory containing `ops-receipts.jsonl` (default `.state/`).
 * @returns Matching receipts (empty array if file doesn't exist).
 */
export function getReceipts(
  filter?: { action?: string; since?: string },
  basePath: string = DEFAULT_BASE,
): OpsReceipt[] {
  let receipts = readAll(basePath);

  if (filter?.action) {
    receipts = receipts.filter((r) => r.action === filter.action);
  }

  if (filter?.since) {
    receipts = receipts.filter((r) => r.timestamp >= filter.since);
  }

  return receipts;
}

/**
 * Supply-chain hardening utilities (P78).
 *
 * Provides static analysis scanning and best-effort sandboxed execution
 * for skill/tool code submitted to the system.
 *
 * Uses only Node.js built-in modules — no external dependencies.
 */

import { createContext, runInNewContext } from "node:vm";

// ── Interfaces ────────────────────────────────────────────────────────

/** Result of a static scan over skill/tool source code. */
export interface ScanResult {
  /** `true` when no dangerous patterns were detected. */
  safe: boolean;
  /** Human-readable descriptions of every detected pattern. */
  warnings: string[];
}

/** Result of a sandboxed execution attempt. */
export interface SandboxResult {
  /** `true` when the code ran to completion without error. */
  success: boolean;
  /** Captured console.log output (newline-joined), present on success. */
  output?: string;
  /** Error message, present on failure. */
  error?: string;
}

// ── Pattern catalogue ─────────────────────────────────────────────────

interface DangerPattern {
  /** RegExp to test against the source code. */
  pattern: RegExp;
  /** Warning string emitted when the pattern matches. */
  message: string;
}

const DANGER_PATTERNS: DangerPattern[] = [
  // Dynamic code execution
  { pattern: /\beval\s*\(/, message: "Dynamic code execution: eval()" },
  { pattern: /\bnew\s+Function\s*\(/, message: "Dynamic code execution: new Function()" },
  { pattern: /(?<!\bnew\s)\bFunction\s*\(/, message: "Dynamic code execution: Function()" },

  // Shell execution
  { pattern: /\bchild_process\b/, message: "Shell execution: child_process module" },
  { pattern: /\bexecSync\s*\(/, message: "Shell execution: execSync()" },
  { pattern: /\bspawnSync\s*\(/, message: "Shell execution: spawnSync()" },
  { pattern: /\bexec\s*\(/, message: "Shell execution: exec()" },

  // Environment variable access
  { pattern: /\bprocess\.env\b/, message: "Environment variable access: process.env" },

  // Dynamic CJS imports
  { pattern: /\brequire\s*\(/, message: "Dynamic import: require()" },

  // Destructive filesystem operations — match both `fs.xxxSync` and bare `xxxSync(`
  // to catch destructured imports like `import { unlinkSync } from "fs"`.
  { pattern: /\bwriteFileSync\b/, message: "Destructive filesystem op: writeFileSync" },
  { pattern: /\bunlinkSync\b/, message: "Destructive filesystem op: unlinkSync" },
  { pattern: /\brmSync\b/, message: "Destructive filesystem op: rmSync" },
  { pattern: /\brmdirSync\b/, message: "Destructive filesystem op: rmdirSync" },

  // Network access
  { pattern: /\bfetch\s*\(/, message: "Network access: fetch()" },
  { pattern: /\bhttp\.request\b/, message: "Network access: http.request" },
  { pattern: /\bhttps\.request\b/, message: "Network access: https.request" },
  { pattern: /\bnet\.connect\b/, message: "Network access: net.connect" },

  // Path traversal via __dirname / __filename combined with ..
  {
    pattern: /(?:__dirname|__filename)[\s\S]{0,40}\.\./,
    message: "Path traversal: __dirname/__filename combined with ..",
  },
  {
    pattern: /\.\.[\s\S]{0,40}(?:__dirname|__filename)/,
    message: "Path traversal: .. combined with __dirname/__filename",
  },
];

/**
 * Regex to detect import/require of a module that is *not*:
 *  - a relative path (starts with `.` or `..`)
 *  - a Node.js built-in (prefixed `node:`)
 *  - a known allowed package
 *
 * We match:
 *   import … from "<specifier>"
 *   import("<specifier>")
 *   require("<specifier>")
 */
const EXTERNAL_IMPORT_RE =
  /(?:from\s+|import\s*\(\s*|require\s*\(\s*)['"]([^'"]+)['"]/g;

/**
 * Packages considered safe / known.
 *
 * Only includes benign Node built-ins and project tooling.
 * Dangerous modules like `child_process`, `net`, `fs`, `http`, `https`
 * are deliberately excluded — importing them generates an
 * "External import" warning (on top of any danger-pattern hits).
 */
const KNOWN_PACKAGES = new Set([
  "vitest",
  "typescript",
  // Benign Node built-ins
  "path",
  "os",
  "util",
  "assert",
  "events",
  "stream",
  "crypto",
  "url",
  "querystring",
  "zlib",
  "buffer",
  "vm",
  "string_decoder",
  "perf_hooks",
  "worker_threads",
]);

/**
 * Check whether a module specifier is an outside-project import.
 * Returns `true` if the specifier looks external and is not in the allowlist.
 */
function isExternalSpecifier(specifier: string): boolean {
  if (specifier.startsWith(".") || specifier.startsWith("/")) return false;
  if (specifier.startsWith("node:")) return false;
  // Strip subpath for scoped and unscoped packages
  const pkg = specifier.startsWith("@")
    ? specifier.split("/").slice(0, 2).join("/")
    : specifier.split("/")[0];
  return !KNOWN_PACKAGES.has(pkg);
}

// ── Public API ────────────────────────────────────────────────────────

/**
 * Statically scan skill/tool source code for dangerous patterns.
 *
 * @param code - The source code string to analyse.
 * @returns A {@link ScanResult} indicating whether the code is safe.
 *
 * @example
 * ```ts
 * const result = scanSkill("const x = 1;");
 * // { safe: true, warnings: [] }
 * ```
 */
export function scanSkill(code: string): ScanResult {
  const warnings: string[] = [];

  // Check every pattern in the catalogue
  for (const { pattern, message } of DANGER_PATTERNS) {
    if (pattern.test(code)) {
      warnings.push(message);
    }
  }

  // Check for external (outside-project) imports
  let match: RegExpExecArray | null;
  // Reset lastIndex since EXTERNAL_IMPORT_RE is global
  EXTERNAL_IMPORT_RE.lastIndex = 0;
  while ((match = EXTERNAL_IMPORT_RE.exec(code)) !== null) {
    const specifier = match[1];
    if (isExternalSpecifier(specifier)) {
      warnings.push(`External import: "${specifier}"`);
    }
  }

  return { safe: warnings.length === 0, warnings };
}

/** Sandbox execution timeout in milliseconds. */
const SANDBOX_TIMEOUT_MS = 5_000;

/**
 * Execute code in a best-effort sandbox using `node:vm`.
 *
 * The sandbox provides **no** access to `require`, `process`, `fs`,
 * `child_process`, or other Node.js globals. Console output is captured
 * and returned as {@link SandboxResult.output}.
 *
 * @param code - JavaScript code to execute (must be valid JS, not TS).
 * @returns A {@link SandboxResult} with captured output or error.
 *
 * @example
 * ```ts
 * const result = sandboxExecute("console.log(1 + 1)");
 * // { success: true, output: "2" }
 * ```
 */
export function sandboxExecute(code: string): SandboxResult {
  const lines: string[] = [];

  // Build a minimal sandbox context — intentionally sparse.
  const sandbox: Record<string, unknown> = {
    console: {
      log: (...args: unknown[]) => {
        lines.push(args.map(String).join(" "));
      },
    },
    // Provide safe globals that most JS expects
    Array,
    Boolean,
    Date,
    Error,
    JSON,
    Map,
    Math,
    Number,
    Object,
    Promise,
    RegExp,
    Set,
    String,
    Symbol,
    parseInt,
    parseFloat,
    isNaN,
    isFinite,
    undefined,
    NaN,
    Infinity,
  };

  const context = createContext(sandbox);

  try {
    runInNewContext(code, context, {
      timeout: SANDBOX_TIMEOUT_MS,
      filename: "sandbox.js",
    });
    return { success: true, output: lines.join("\n") };
  } catch (err: unknown) {
    const message =
      err instanceof Error ? err.message : String(err);
    return { success: false, error: message };
  }
}
